# Calabria Meteo Lab - estensione visiva della home
# Scena artistica interattiva, non simulazione meteorologica.

HOME_VIVA = '<style>\n.cml-home-hero.cml-living{display:grid!important;grid-template-columns:minmax(0,1fr) minmax(360px,1.1fr);gap:32px;align-items:center;padding:42px!important;min-height:620px;background:radial-gradient(ellipse at 85% 0,#146a7a,transparent 55%),linear-gradient(135deg,#061e30,#08465a)!important}\n.cml-living .cml-hero-content{max-width:none!important;padding:10px!important;background:none!important;border:0!important;backdrop-filter:none!important}\n.cml-living h1{font-size:clamp(48px,5.5vw,82px)!important}\n.cml-living .cml-hero-lead{font-size:18px!important;font-weight:500!important}\n.cml-living .cml-hero-visual{display:none!important}\n.cml-lab{position:relative;z-index:4;border:1px solid #ffffff28;background:#071c2fa6;border-radius:26px;overflow:hidden;box-shadow:0 28px 70px #00142266;color:#eefaff;min-width:0}\n.cml-lab .lab-title{display:flex;justify-content:space-between;gap:10px;padding:16px 20px;font-size:12px;letter-spacing:1px;align-items:center}\n.cml-lab .lab-title span{color:#a5d5dc;font-size:10px;letter-spacing:.5px}\n.cml-lab canvas{width:100%;height:310px;display:block;touch-action:pan-y}\n.cml-lab .lab-controls{padding:18px 20px;background:#082235}\n.cml-lab .lab-presets{display:flex;flex-wrap:wrap;gap:7px;margin-bottom:16px}\n.cml-lab button{color:#d9f4ff;background:#15394b;border:1px solid #ffffff24;border-radius:999px;padding:8px 12px;cursor:pointer;font:inherit;font-size:12px}\n.cml-lab button:hover{background:#215368}.cml-lab button[aria-pressed=true]{background:#91e3d3;color:#092b39}\n.cml-lab .lab-sliders{display:grid;grid-template-columns:1fr 1fr;gap:14px 18px}\n.cml-lab label{display:block;font-size:12px;color:#bde2ea}.cml-lab output{float:right;color:#fff;font-variant-numeric:tabular-nums}\n.cml-lab input{width:100%;accent-color:#89e2d5;margin-top:10px;cursor:ew-resize}\n.cml-lab .lab-note{font-size:11px;color:#a4c5d2;line-height:1.6;margin:15px 0 0}\n.cml-lab :focus-visible{outline:3px solid #ffe394;outline-offset:4px}\n@media(max-width:1000px){.cml-home-hero.cml-living{grid-template-columns:1fr;padding:25px!important;gap:20px}.cml-lab canvas{height:290px}}\n@media(max-width:480px){.cml-lab .lab-sliders{grid-template-columns:1fr}.cml-home-hero.cml-living{padding:18px!important}.cml-lab canvas{height:260px}}\n</style>\n<script>\n(()=>{\nfunction init(){\nconst hero=document.querySelector(\'.cml-home-hero\');if(!hero||hero.querySelector(\'.cml-lab\'))return;\nhero.classList.add(\'cml-living\');\nconst lab=document.createElement(\'section\');lab.className=\'cml-lab\';lab.setAttribute(\'aria-label\',\'Laboratorio visivo meteorologico\');\nlab.innerHTML=`<div class="lab-title">ATMOSFERA VIVA <span>SCENA INTERATTIVA</span></div>\n<canvas role="img" aria-label="Paesaggio illustrativo con cielo, nuvole, rilievi e mare animati"></canvas>\n<div class="lab-controls"><div class="lab-presets"><button type="button" data-preset="alba">Alba</button><button type="button" data-preset="sereno">Sereno</button><button type="button" data-preset="pioggia">Pioggia</button><button type="button" data-preset="notte">Notte</button><button type="button" id="lab-pause" aria-pressed="false">⏸ Pausa</button></div>\n<div class="lab-sliders">\n<label>Ora della scena <output id="lab-hour-v"></output><input id="lab-hour" type="range" min="0" max="24" value="17" step="0.1"></label>\n<label>Movimento del vento <output id="lab-wind-v"></output><input id="lab-wind" type="range" min="0" max="100" value="35"></label>\n<label>Nuvole nella scena <output id="lab-cloud-v"></output><input id="lab-cloud" type="range" min="0" max="100" value="25"></label>\n<label>Effetto pioggia <output id="lab-rain-v"></output><input id="lab-rain" type="range" min="0" max="100" value="0"></label>\n</div><p class="lab-note">Modifica il cielo e muovi il puntatore sul paesaggio. Scena artistica: i controlli non rappresentano osservazioni, previsioni o una simulazione fisica. Il vento regola solo la velocità dell’animazione.</p></div>`;\nhero.append(lab);\nconst canvas=lab.querySelector(\'canvas\'),ctx=canvas.getContext(\'2d\');if(!ctx)return;\nconst $=id=>lab.querySelector(\'#lab-\'+id),state={hour:17,wind:35,cloud:25,rain:0};\nlet w=600,h=310,t=0,last=0,raf=0,paused=matchMedia(\'(prefers-reduced-motion: reduce)\').matches,visible=true,mx=0,my=0;\nconst stars=Array.from({length:65},(_,i)=>({x:((i*73.37)%100)/100,y:((i*37.73)%65)/100,r:.6+(i%3)*.4}));\nfunction sync(){[\'hour\',\'wind\',\'cloud\',\'rain\'].forEach(k=>{$(k).value=state[k];const v=state[k];$(k+\'-v\').textContent=k===\'hour\'?String(Math.floor(v)%24).padStart(2,\'0\')+\':\'+String(Math.floor((v%1)*60)).padStart(2,\'0\'):k===\'cloud\'||k===\'rain\'?v+\'%\':v<25?\'Lento\':v<65?\'Moderato\':\'Rapido\'});draw()}\nfunction resize(){const r=canvas.getBoundingClientRect();w=r.width||600;h=r.height||310;const d=Math.min(devicePixelRatio||1,2);canvas.width=Math.round(w*d);canvas.height=Math.round(h*d);ctx.setTransform(d,0,0,d,0,0);draw()}\nfunction circle(x,y,r,fill){ctx.beginPath();ctx.arc(x,y,r,0,Math.PI*2);ctx.fillStyle=fill;ctx.fill()}\nfunction draw(){\nconst hour=state.hour%24,day=hour>=6&&hour<19,twilight=day&&(hour<8||hour>16),px=mx*8,py=my*5;\nconst grad=ctx.createLinearGradient(0,0,0,h);grad.addColorStop(0,day?(twilight?\'#29365c\':\'#126a99\'):\'#051329\');grad.addColorStop(.65,day?(twilight?\'#e19a83\':\'#80d4e0\'):\'#244b70\');grad.addColorStop(1,\'#0e5264\');ctx.fillStyle=grad;ctx.fillRect(0,0,w,h);\nif(!day){stars.forEach((s,i)=>circle(s.x*w+px*.3,s.y*h,s.r,\'rgba(229,245,255,\'+(.45+.25*Math.sin(t*.8+i))+\')\'))}\nconst progress=day?(hour-6)/13:((hour+5)%24)/11;\nconst sx=w*(.15+.7*Math.max(0,Math.min(1,progress)))+px,sy=h*(.44-.29*Math.sin(Math.PI*Math.max(0,Math.min(1,progress))))+py;\nconst glow=ctx.createRadialGradient(sx,sy,0,sx,sy,day?100:65);glow.addColorStop(0,day?\'#ffe9aeaa\':\'#d2e9ff77\');glow.addColorStop(1,\'#ffe9ae00\');ctx.fillStyle=glow;ctx.fillRect(0,0,w,h);circle(sx,sy,day?23:16,day?\'#ffe2a0\':\'#d6eafa\');if(!day)circle(sx+7,sy-5,14,\'#142f4d\');\nconst n=Math.round(state.cloud/10);for(let i=0;i<n;i++){const cw=58+(i%3)*22,x=((i*.217*w+t*(2+state.wind*.16))%(w+cw*3))-cw,y=h*(.19+(i%4)*.065)+py*.5;ctx.fillStyle=day?\'rgba(238,245,249,.73)\':\'rgba(108,137,165,.48)\';ctx.beginPath();ctx.ellipse(x,y,cw,12,0,0,Math.PI*2);ctx.ellipse(x-cw*.3,y-7,cw*.48,18,0,0,Math.PI*2);ctx.ellipse(x+cw*.2,y-9,cw*.38,21,0,0,Math.PI*2);ctx.fill()}\nfor(let layer=0;layer<3;layer++){const base=h*(.59+layer*.065);ctx.beginPath();ctx.moveTo(0,h);for(let x=0;x<=w+5;x+=5){const y=base-Math.sin(x/w*7+layer*1.5)*h*.05-Math.sin(x/w*13+layer)*h*.025+my*layer*2;ctx.lineTo(x,y)}ctx.lineTo(w,h);ctx.closePath();ctx.fillStyle=[\'#356077\',\'#24555f\',\'#184b48\'][layer];ctx.fill()}\nconst sea=h*.77;const sg=ctx.createLinearGradient(0,sea,0,h);sg.addColorStop(0,day?\'#237e94\':\'#174761\');sg.addColorStop(1,\'#072e47\');ctx.fillStyle=sg;ctx.fillRect(0,sea,w,h-sea);\nfor(let j=0;j<8;j++){ctx.beginPath();for(let x=0;x<=w;x+=5){const y=sea+10+j*10+Math.sin(x*.028+t*(.5+state.wind*.017)+j)* (2+j*.2);x===0?ctx.moveTo(x,y):ctx.lineTo(x,y)}ctx.strokeStyle=\'rgba(163,230,235,\'+(.2-j*.018)+\')\';ctx.lineWidth=1;ctx.stroke()}\nconst drops=Math.round(state.rain*1.5);ctx.strokeStyle=\'#c7edff80\';ctx.lineWidth=1;ctx.beginPath();for(let i=0;i<drops;i++){const x=((i*67.31+t*(18+state.wind))%(w+70))-35,y=(i*43.71+t*220)%(h+30)-15;ctx.moveTo(x,y);ctx.lineTo(x-3-state.wind*.09,y+12)}ctx.stroke();\nctx.fillStyle=\'#061e3077\';ctx.fillRect(0,h-27,w,27);ctx.fillStyle=\'#e1f4fa\';ctx.font=\'10px system-ui\';ctx.fillText(\'PAESAGGIO ILLUSTRATIVO · NON DATI METEO\',15,h-10);\n}\nfunction frame(now){raf=0;if(paused||!visible||document.hidden){last=0;return}if(last)t+=Math.min((now-last)/1000,.05);last=now;draw();raf=requestAnimationFrame(frame)}\nfunction start(){if(!raf&&!paused&&visible&&!document.hidden)raf=requestAnimationFrame(frame)}\nfunction halt(){if(raf)cancelAnimationFrame(raf);raf=0;last=0}\nfunction pauseUI(){$(\'pause\').textContent=paused?\'▶ Anima\':\'⏸ Pausa\';$(\'pause\').setAttribute(\'aria-pressed\',String(paused))}\n$(\'pause\').onclick=()=>{paused=!paused;pauseUI();paused?halt():start()};\n[\'hour\',\'wind\',\'cloud\',\'rain\'].forEach(k=>$(k).addEventListener(\'input\',()=>{state[k]=Number($(k).value);lab.querySelectorAll(\'[data-preset]\').forEach(b=>b.setAttribute(\'aria-pressed\',\'false\'));sync()}));\nconst presets={alba:{hour:6.8,wind:20,cloud:20,rain:0},sereno:{hour:13,wind:25,cloud:10,rain:0},pioggia:{hour:15,wind:65,cloud:90,rain:70},notte:{hour:23,wind:15,cloud:10,rain:0}};\nlab.querySelectorAll(\'[data-preset]\').forEach(b=>{b.setAttribute(\'aria-pressed\',\'false\');b.onclick=()=>{Object.assign(state,presets[b.dataset.preset]);lab.querySelectorAll(\'[data-preset]\').forEach(x=>x.setAttribute(\'aria-pressed\',String(x===b)));sync()}});\ncanvas.addEventListener(\'pointermove\',e=>{const r=canvas.getBoundingClientRect();mx=(e.clientX-r.left)/r.width-.5;my=(e.clientY-r.top)/r.height-.5;if(paused)draw()});canvas.addEventListener(\'pointerleave\',()=>{mx=0;my=0;if(paused)draw()});\nnew ResizeObserver(resize).observe(canvas);\nnew IntersectionObserver(entries=>{visible=entries[0].isIntersecting;visible?start():halt()},{threshold:.05}).observe(lab);\ndocument.addEventListener(\'visibilitychange\',()=>document.hidden?halt():start());\npauseUI();sync();resize();start();\n}\nif(document.readyState===\'loading\')document.addEventListener(\'DOMContentLoaded\',init);else init();\n})();\n</script>'

def aggiungi_home_viva(documento):
    if '</body>' not in documento:
        return documento + HOME_VIVA
    return documento.replace('</body>', HOME_VIVA + '\n</body>', 1)
